// Golden News API responses generated by the backend (backend/tests/fixtures/news/news_*.json, written by
// backend/scripts/write_news_fixtures.py). Orchestrator-owned: never edit a JSON file by hand, copy the
// regenerated set instead. They live in their own folder so the Home fixture list (29 files) stays as it is.
// Tests load them through newsFixture().
import type { NewsResponse } from "../types";

const files = import.meta.glob("./news/*.json", { eager: true, import: "default" }) as Record<string, unknown>;

export function newsFixture<T = NewsResponse>(name: string): T {
  const key = `./news/${name}.json`;
  if (!(key in files)) throw new Error(`unknown News fixture: ${name}`);
  return structuredClone(files[key]) as T;
}

export const NEWS_FIXTURE_NAMES = Object.keys(files).map(key => key.slice("./news/".length, -5)).sort();
